-- ─────────────────────────────────────────────────────────────────────────────
-- whatsappMessageDeliveries — Meta delivery receipt of every OUTBOUND WhatsApp
-- message (POS staff replies, staff templates, agent replies): one row per wamid.
-- Feeds the ✓ / ✓✓ / ✓✓ azul / ⚠️ ticks on the POS chat bubbles.
--
-- Generated by posgmo-factory from tests/prd_whatsappMessageDelivery.json
-- (2026-11-12, FACTORY_SQL_MODE=validate: compiled + rolled back on the live DB).
-- Hand fixes to the generated SP (factory review did not pass, no PR was opened):
--   1. 'failed' ranked above 'read' and overwrote delivered/read receipts —
--      now failed only replaces accepted/sent.
--   2. A row created by the webhook ('sent' arrives ~1 s after the send) was never
--      linked: the send-side 'accepted' (lower rank) skipped the whole UPDATE, so
--      whatsappMessageId/senderKind stayed NULL. Now every MATCHED row is updated:
--      link + timestamps always COALESCE in, only status is rank-gated.
--   3. The duplicate-payload check jumped past COMMIT and left a transaction open.
--   Read SPs (_all/_one) and the CRUD route were dropped: the POS reads receipts
--   joined in sp_whatsappAgentConversations 'thread'; nothing calls them.
--
-- Input: { "whatsappMessageDeliveries": [{ "action": 1, "companyId", "providerMessageId",
--          "whatsappMessageId"?, "channelId", "senderKind"?, "status",
--          "statusTimestamp"? (unix s, UTC), "errorCode"?, "errorTitle"? }] }
-- Output: one row (value = whatsappMessageDeliveryId, msg, error).
-- ─────────────────────────────────────────────────────────────────────────────

IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'whatsappMessageDeliveries')
BEGIN
    CREATE TABLE [dbo].[whatsappMessageDeliveries] (
        whatsappMessageDeliveryId INT IDENTITY(1,1) NOT NULL,
        companyId INT NOT NULL,
        providerMessageId NVARCHAR(100) NOT NULL,
        whatsappMessageId INT NULL,
        channelId INT NOT NULL,
        senderKind NVARCHAR(20) NULL,
        status NVARCHAR(20) NOT NULL,
        sentAt DATETIME NULL,
        deliveredAt DATETIME NULL,
        readAt DATETIME NULL,
        failedAt DATETIME NULL,
        errorCode NVARCHAR(20) NULL,
        errorTitle NVARCHAR(200) NULL,
        created_At DATETIME NOT NULL DEFAULT GETDATE(),
        updated_at DATETIME NULL,
        CONSTRAINT PK_whatsappMessageDeliveries PRIMARY KEY CLUSTERED (whatsappMessageDeliveryId ASC),
        CONSTRAINT UQ_whatsappMessageDeliveries_providerMessageId UNIQUE NONCLUSTERED (providerMessageId ASC),
        CONSTRAINT FK_whatsappMessageDeliveries_companies FOREIGN KEY (companyId) REFERENCES dbo.companies(companyId),
        CONSTRAINT FK_whatsappMessageDeliveries_whatsappMessages FOREIGN KEY (whatsappMessageId) REFERENCES dbo.whatsappMessages(messageId),
        CONSTRAINT FK_whatsappMessageDeliveries_whatsappChannels FOREIGN KEY (channelId) REFERENCES dbo.whatsappChannels(channelId),
        CONSTRAINT CK_whatsappMessageDeliveries_status CHECK (status IN ('accepted','sent','delivered','read','failed'))
    );

    CREATE NONCLUSTERED INDEX IX_whatsappMessageDeliveries_companyId ON dbo.whatsappMessageDeliveries (companyId);
    CREATE NONCLUSTERED INDEX IX_whatsappMessageDeliveries_whatsappMessageId ON dbo.whatsappMessageDeliveries (whatsappMessageId) INCLUDE (status, errorCode);
    CREATE NONCLUSTERED INDEX IX_whatsappMessageDeliveries_channelId ON dbo.whatsappMessageDeliveries (channelId);
    CREATE NONCLUSTERED INDEX IX_whatsappMessageDeliveries_created_At ON dbo.whatsappMessageDeliveries (created_At);
END
GO

CREATE OR ALTER PROC [dbo].[sp_whatsappMessageDeliveries]
    @pjsonfile VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Outputmessage NVARCHAR(MAX) = '{
      "result": [
        { "value": "", "msg": "", "error": "" }
      ]
    }';

    DECLARE @action INT = (
        SELECT TOP 1 TRY_CONVERT(INT, JSON_VALUE(value, '$.action'))
        FROM OPENJSON(@pjsonfile, '$.whatsappMessageDeliveries'));

    DECLARE @payload TABLE (
        companyId INT NULL,
        providerMessageId NVARCHAR(100) NULL,
        whatsappMessageId INT NULL,
        channelId INT NULL,
        senderKind NVARCHAR(20) NULL,
        status NVARCHAR(20) NULL,
        statusRank INT NULL,
        statusAt DATETIME NULL,
        errorCode NVARCHAR(20) NULL,
        errorTitle NVARCHAR(200) NULL
    );

    INSERT INTO @payload (companyId, providerMessageId, whatsappMessageId, channelId, senderKind,
                          status, statusRank, statusAt, errorCode, errorTitle)
    SELECT
        TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        JSON_VALUE(value, '$.providerMessageId'),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.whatsappMessageId')),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.channelId')),
        JSON_VALUE(value, '$.senderKind'),
        JSON_VALUE(value, '$.status'),
        -- failed has no rank of its own: it only replaces accepted/sent (rule below).
        CASE JSON_VALUE(value, '$.status')
            WHEN 'accepted' THEN 0 WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'read' THEN 3 END,
        CASE WHEN TRY_CONVERT(BIGINT, JSON_VALUE(value, '$.statusTimestamp')) IS NOT NULL
             THEN DATEADD(SECOND, TRY_CONVERT(BIGINT, JSON_VALUE(value, '$.statusTimestamp')), '1970-01-01') END,
        LEFT(JSON_VALUE(value, '$.errorCode'), 20),
        LEFT(JSON_VALUE(value, '$.errorTitle'), 200)
    FROM OPENJSON(@pjsonfile, '$.whatsappMessageDeliveries');

    IF @action IS NULL OR @action NOT IN (1, 2)
       OR EXISTS (SELECT 1 FROM @payload
                  WHERE ISNULL(providerMessageId, '') = '' OR companyId IS NULL OR channelId IS NULL
                     OR status NOT IN ('accepted', 'sent', 'delivered', 'read', 'failed') OR status IS NULL)
       OR EXISTS (SELECT 1 FROM @payload GROUP BY providerMessageId HAVING COUNT(*) > 1)
    BEGIN
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg',
            'action 1|2 with providerMessageId, companyId, channelId and a valid status (one row per wamid) are required');
    END
    ELSE
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @ids TABLE (whatsappMessageDeliveryId INT);

        MERGE dbo.whatsappMessageDeliveries WITH (SERIALIZABLE, UPDLOCK, HOLDLOCK) AS t
        USING @payload AS s
        ON t.providerMessageId = s.providerMessageId
        WHEN MATCHED THEN UPDATE SET
            -- The link and the per-status timestamps always fill in (first value wins),
            -- whatever order Meta's receipts and our own send-side row arrive in.
            t.whatsappMessageId = COALESCE(t.whatsappMessageId, s.whatsappMessageId),
            t.senderKind        = COALESCE(t.senderKind, s.senderKind),
            t.sentAt            = COALESCE(t.sentAt,      CASE WHEN s.status = 'sent'      THEN s.statusAt END),
            t.deliveredAt       = COALESCE(t.deliveredAt, CASE WHEN s.status IN ('delivered', 'read') THEN s.statusAt END),
            t.readAt            = COALESCE(t.readAt,      CASE WHEN s.status = 'read'      THEN s.statusAt END),
            t.failedAt          = COALESCE(t.failedAt,    CASE WHEN s.status = 'failed'    THEN s.statusAt END),
            -- Status only moves forward; failed only replaces accepted/sent.
            t.status = CASE
                WHEN s.status = 'failed' AND t.status IN ('accepted', 'sent') THEN 'failed'
                WHEN s.status <> 'failed' AND t.status <> 'failed'
                     AND s.statusRank > CASE t.status WHEN 'accepted' THEN 0 WHEN 'sent' THEN 1
                                                      WHEN 'delivered' THEN 2 WHEN 'read' THEN 3 END
                    THEN s.status
                ELSE t.status END,
            t.errorCode  = CASE WHEN s.status = 'failed' AND t.status IN ('accepted', 'sent')
                                THEN COALESCE(s.errorCode, t.errorCode) ELSE t.errorCode END,
            t.errorTitle = CASE WHEN s.status = 'failed' AND t.status IN ('accepted', 'sent')
                                THEN COALESCE(s.errorTitle, t.errorTitle) ELSE t.errorTitle END,
            t.updated_at = GETDATE()
        WHEN NOT MATCHED BY TARGET THEN
            INSERT (companyId, providerMessageId, whatsappMessageId, channelId, senderKind, status,
                    sentAt, deliveredAt, readAt, failedAt, errorCode, errorTitle)
            VALUES (s.companyId, s.providerMessageId, s.whatsappMessageId, s.channelId, s.senderKind, s.status,
                    CASE WHEN s.status = 'sent' THEN s.statusAt END,
                    CASE WHEN s.status IN ('delivered', 'read') THEN s.statusAt END,
                    CASE WHEN s.status = 'read' THEN s.statusAt END,
                    CASE WHEN s.status = 'failed' THEN s.statusAt END,
                    CASE WHEN s.status = 'failed' THEN s.errorCode END,
                    CASE WHEN s.status = 'failed' THEN s.errorTitle END)
        OUTPUT INSERTED.whatsappMessageDeliveryId INTO @ids;

        COMMIT TRANSACTION;

        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value',
                                         CONVERT(NVARCHAR(20), (SELECT TOP 1 whatsappMessageDeliveryId FROM @ids)));
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Delivery status upserted');
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', ERROR_MESSAGE());
    END CATCH;

    SELECT
        JSON_VALUE(value, '$.value') AS value,
        JSON_VALUE(value, '$.msg')   AS msg,
        JSON_VALUE(value, '$.error') AS error
    FROM OPENJSON(@Outputmessage, '$.result');
END;
GO
